def find_literals(text: str, pattern: str) -> tuple:
    # Using regex to find all occurrences of the pattern
    matches = re.finditer(pattern, text)

    if matches:
        match = next(matches)
        start = match.start()  # Starting index of the first occurrence
        end = match.end()  # Ending index of the last occurrence
        return (pattern, start, end)
    else:
        return None  # If no match is found, return None

