def get_median(arr1, arr2, n):
    # Combine both arrays and sort them
    merged_arr = sorted(arr1 + arr2)

    # Calculate the index of the middle element
    mid_index = n // 2

    # Return the median value
    if n % 2 != 0:
        return float(merged_arr[mid_index])
    else:
        return (merged_arr[mid_index - 1] + merged_arr[mid_index]) / 2

