def find_First_Missing(arr, start_index, end_index):
    # If there are no elements in the array, return the first index as the missing number
    if not arr:
        return start_index

    # Use binary search to find the smallest missing number
    while start_index <= end_index:
        mid = (start_index + end_index) // 2

        # Check if the middle element is at its correct position
        if arr[mid] == mid + start_index:
            start_index = mid + 1
        else:
            end_index = mid - 1

    # Return the next index after the last found element
    return start_index + 1

