def remove_parenthesis(s):
    # find all indices of parentheses in the string
    start = s.find('(')
    end = s.rfind(')')

    # if there are no parentheses, return the string as it is
    if start == -1 and end == -1:
        return s

    # remove the parentheses from the string
    return s[:start] + s[end+1:]

