def max_sum_of_three_consecutive(nums, n):
    # Handle edge cases where there are fewer than three elements
    if n < 3:
        return 0

    # Initialize the first three sums with the first two elements
    dp = [nums[0], nums[1] + nums[0], nums[2] + nums[0] + nums[1]]

    # Calculate the maximum sum for each subsequent element
    for i in range(3, n):
        dp.append(max(dp[i-1], dp[i-2], dp[i-3]) + nums[i])

    # Return the maximum sum among the last three elements
    return max(dp[-3:])

