def smallest_prime_divisor(n):
    # Check divisibility by 2 first
    if n % 2 == 0:
        return 2

    # Check for odd factors starting from 3
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return i

    # If no divisors found (n is prime), return n itself
    return n

# Example usage
