def sum_of_primes(n):
    """
    Find the sum of all prime numbers between 1 and n (inclusive).

    Args:
    n (int): The upper limit (inclusive) for finding prime numbers.

    Returns:
    int: The sum of all prime numbers between 1 and n.
    """
    def is_prime(num):
        """Check if a number is prime."""
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        max_divisor = int(num ** 0.5) + 1
        for divisor in range(3, max_divisor, 2):
            if num % divisor == 0:
                return False
        return True

    primes_sum = 0
    for i in range(1, n+1):
        if is_prime(i):
            primes_sum += i
    return primes_sum

