    """Calculate the greatest common divisor of two numbers using recursion."""
    # Base case: if one number is zero, the gcd is the other number
    if x == 0:
        return y
    elif y == 0:
        return x
    else:
        # Recursive case: apply the Euclidean algorithm
        return recur_gcd(y, x % y)

