def min_jumps(arr, n):
    if not arr or n <= 1:
        return 0

    # Initialize the dp array with infinity and set the first element to 0
    dp = [float('inf')] * n
    dp[0] = 0

    # Fill the dp array
    for i in range(1, n):
        for j in range(i):
            if j + arr[j] >= i:
                dp[i] = min(dp[i], dp[j] + 1)

    return dp[-1]

