def last_two_digits(n):
    # The last two digits of n! will be at most 5 * (n-1)!
    if n <= 4:
        return n % 100

    # Calculate factorial and take modulo 100 to get the last two digits
    factorial = 1
    for i in range(2, n + 1):
        factorial = (factorial * i) % 100

    return factorial

