def count_Fac(n):
    count = {}

    # Divide n by 2 until it becomes odd
    while n % 2 == 0:
        if 2 in count:
            count[2] += 1
        else:
            count[2] = 1
        n //= 2

    # Now n must be odd, start from 3 and check only odd numbers
    for i in range(3, int(n**0.5)+1, 2):
        while n % i == 0:
            if i in count:
                count[i] += 1
            else:
                count[i] = 1
            n //= i

    # This condition is to handle the case when n is a prime number greater than 2
    if n > 2:
        if n in count:
            count[n] += 1
        else:
            count[n] = 1

    return len(count)

