def count_fac(n):
    if n < 1: return 0  # No factors for non-positive numbers
    distinct_factors = set()

    # Check for each number from 2 up to the square root of n
    for i in range(2, int(n**0.5) + 1):
        while n % i == 0:
            distinct_factors.add(i)
            n //= i

    # If n is greater than 1 (n itself is a prime number), add it to the set
    if n > 1:
        distinct_factors.add(n)

    return len(distinct_factors)

