def find_first_occurrence(sorted_array, target):
    """
    Find the index of the first occurrence of a given number in a sorted array.

    Args:
    sorted_array (list): A list of integers sorted in ascending order.
    target (int): The integer to search for in the sorted array.

    Returns:
    int: The index of the first occurrence of the target, or -1 if not found.
    """
    left, right = 0, len(sorted_array) - 1

    while left <= right:
        mid = (left + right) // 2

        if sorted_array[mid] < target:
            left = mid + 1
        elif sorted_array[mid] > target:
            right = mid - 1
        else:
            # If mid is the first occurrence or the previous element is not equal to the target
            if mid == 0 or sorted_array[mid-1] != target:
                return mid
            else:
                right = mid - 1

    return -1

