def find_first_occurrence(arr, num):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] < num:
            left = mid + 1
        elif arr[mid] > num:
            right = mid - 1
        else:
            # If mid is at the first occurrence or previous element is not equal to num
            if mid == 0 or arr[mid-1] != num:
                return mid
            right = mid - 1

    return -1

# Example usage
