def lcs_of_three(s1: str, s2: str, s3: str, m: int, n: int, o: int) -> int:
    # Initialize the DP table with zeros
    dp = [[0] * (n + 1) for _ in range(o + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            for k in range(1, o + 1):
                if s1[i - 1] == s2[j - 1] == s3[k - 1]:
                    dp[k][j] = dp[k - 1][j - 1] + 1
                else:
                    dp[k][j] = max(dp[k - 1][j], dp[k][j - 1], dp[k - 1][j - 1])

    return dp[o][n]

