def lcs_of_three(s1, s2, s3, n1, n2, n3):
    # Create a table to store lengths of LCSs of substrings
    dp = [[0 for _ in range(n3 + 1)] for _ in range(n2 + 1)]

    # Build the DP table
    for i in range(1, n2 + 1):
        for j in range(1, n3 + 1):
            if s2[i - 1] == s3[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

