    for i in range(1, n2 + 1):
        for j in range(1, n3 + 1):
            if s2[i - 1] == s3[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

