def get_Pairs_Count(arr, n, sum):
    # Create an empty dictionary to store the frequency of elements
    map = {}

    # Traverse through all elements and store their frequencies in the map
    for i in range(n):
        if arr[i] in map:
            map[arr[i]] += 1
        else:
            map[arr[i]] = 1

    count = 0

    # Check every element in the array for its complement that would make the pair with sum 'sum'
    for j in range(n):
        complement = sum - arr[j]

        # If the complement is found in the map, add its frequency to the count
        if complement in map:
            count += map[complement]

    return count

