def count_divisors(n):
    # Initialize divisor count
    div_count = 0

    # Loop through possible divisors from 1 to sqrt(n)
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            # If i divides n without remainder, increment the divisor count by 2
            div_count += 2

            # If i and n/i are different (i.e., not a perfect square), increment again
            if i != n // i:
                div_count += 1

    return "Even" if div_count % 2 == 0 else "Odd"

