def remove_nested(tup):
    # Initialize an empty list to store the final result
    result = []

    # Iterate through each element in the input tuple
    for item in tup:
        # Check if the current item is a tuple
        if isinstance(item, tuple):
            # Recursively call the function with the inner tuple and extend the result list
            result.extend(remove_nested(item))
        else:
            # If it's not a tuple, append it directly to the result list
            result.append(item)

    # Return the modified list which now contains no nested tuples
    return tuple(result)

# Test the function with the provided example
assert remove_nested((1, 5, 7, (4, 6), 10)) == (1, 5, 7, 10)

