        return -1

    mid = l // 2

    # If the middle element is equal to x,
    # then check for elements to its left.
    if arr[mid] == x:
        # If there are no elements on the left,
        # or the leftmost element is not equal to x,
        # then return the current index.
        return mid if mid == 0 or arr[mid - 1] != x else last(arr, x, mid - 1)

    # If the middle element is greater than x,
    # then search in the left half of the array.
    elif arr[mid] > x:
        return last(arr, x, mid - 1)

    # Otherwise, search in the right half of the array.
    else:
        return last(arr, x, mid + 1)

