    for i in range(1, len(lst)):
        if lst[i] == lst[i-1]:
            count += 1
        else:
            result.append(count)
            count = 1

    # Append the last occurrence
    result.append(count)

    freq_list = [lst[i-1] for i in range(len(result))]
    count_list = result

    return (freq_list, count_list)

