def count_Pairs(arr, n):
    # Dictionary to store counts of elements
    count_dict = {}

    # Count occurrences of each element
    for i in range(n):
        if arr[i] in count_dict:
            count_dict[arr[i]] += 1
        else:
            count_dict[arr[i]] = 1

    # Calculate total number of equal pairings
    total_pairs = 0
    for key, value in count_dict.items():
        # Sum of combinations formula C(n,2)
        total_pairs += (value * (value - 1)) // 2

    return total_pairs

