def factorial(n):
    if n == 0 or n == 1:
        return 1
    else:
        fact = 1
        for i in range(2, n + 1):
            fact *= i
        return fact

def find_Digits(num):
    # Calculate factorial of the given number
    factorial_value = factorial(num)

    # Convert the factorial value to string to count individual digits
    str_fact_value = str(factorial_value)

    # Return the length of the string representing the factorial
    return len(str_fact_value)

