def find_Min_Swaps(arr, n):
    # Count the number of ones and zeros in the array
    count_ones = arr.count(1)
    count_zeros = n - count_ones

    # If there are more ones than zeros, swap them
    if count_ones > count_zeros:
        arr[0], arr[count_ones] = arr[count_ones], arr[0]

    # Count the total number of swaps
    swaps = 0
    for i in range(n):
        # Find the first zero from the left
        while arr[i] != 0:
            i += 1

        # Count the number of ones between the current zero and the next one
        for j in range(i + 1, n):
            if arr[j] == 1:
                swaps += 1

    return swaps

