def find_Min_Swaps(arr, n):
    # Find position of first '1'
    min_index = -1
    for i in range(n):
        if arr[i] == 1:
            if min_index == -1 or i < min_index:
                min_index = i

    # If all elements are 1s, no swaps are needed
    if min_index == -1:
        return 0

    # Count number of 0s before '1' and after '1'
    zero_count_before = 0
    zero_count_after = 0
    for i in range(min_index):
        if arr[i] == 0:
            zero_count_before += 1

    for i in range(min_index + 1, n):
        if arr[i] == 0:
            zero_count_after += 1

    # Minimum swaps required is the sum of 0s before and after '1'
    return zero_count_before + zero_count_after

