def n_common_words(text, n):
    # Split the input text into words and count their occurrences
    word_count = {}
    for word in text.split():
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1

    # Sort the dictionary by occurrence in descending order
    sorted_word_counts = sorted(word_count.items(), key=lambda item: item[1], reverse=True)

    # Return the top n most common words
    return [word for word, _ in sorted_word_counts[:n]]

