def find_longest_conseq_subseq(nums, n):
    # Initialize dictionary to keep track of lengths of subsequences ending at each number
    hash_map = {i: 0 for i in range(1, n+1)}

    # Calculate lengths of subsequences ending at each number
    for i in nums:
        if (i - 1 not in hash_map):
            hash_map[i] = max(hash_map[i-1], 0)
        else:
            hash_map[i] = hash_map[i-1] + 1

    # Find the maximum length among all subsequences
    return max(hash_map.values())

