def length_Of_Last_Word(s):
    # Strip any leading or trailing spaces from the string
    s = s.strip()

    # Find the position of the first non-space character
    first_non_space_index = s.find(' ')

    # If no space is found, return the length of the entire string
    if first_non_space_index == -1:
        return len(s)

    # Otherwise, return the length of the substring starting from the first non-space character
    else:
        return len(s) - first_non_space_index - 1

