def lcm(x, y):
    # Calculate greatest common divisor (GCD)
    def gcd(a, b):
        while b != 0:
            a, b = b, a % b
        return a

    # LCM formula: lcm(x, y) = |x * y| / GCD(x, y)
    return abs(x*y) // gcd(x, y)

# Test the function with provided data points
assert lcm(4,6) == 12
assert lcm(25,30) == 150
assert lcm(100,50) == 500

