def all_Bits_Set_In_The_Given_Range(x, start, end):
    # Convert x to binary string and remove '0b' prefix
    bin_x = bin(x)[2:]

    # Check if every bit from start to end is set (1)
    for i in range(start - 1, end):
        if bin_x[i] != '1':
            return False

    return True

# Example usage
