def is_isomorphic(s1, s2):
    # Check if lengths of both strings are equal
    if len(s1) != len(s2):
        return False

    # Dictionary to store mapping from characters in s1 to characters in s2
    char_map = {}

    for i in range(len(s1)):
        # If character in s1 is already mapped and maps to different character in s2, return False
        if s1[i] in char_map and char_map[s1[i]] != s2[i]:
            return False
        # If character in s1 is not mapped yet, add mapping
        else:
            char_map[s1[i]] = s2[i]

    # If no character in s1 maps to a character in s2, it means they are isomorphic
    return True

# Test case
print(is_isomorphic("paper", "title"))  # Output: True

