def is_isomorphic(s: str, t: str) -> bool:
    # Dictionary to store mappings from s to t
    map_s_to_t = {}
    # Dictionary to store mappings from t to s
    map_t_to_s = {}

    for char_s, char_t in zip(s, t):
        # If both characters are already mapped, they should map to the same characters
        if char_s in map_s_to_t and map_s_to_t[char_s] != char_t:
            return False
        if char_t in map_t_to_s and map_t_to_s[char_t] != char_s:
            return False

        # Otherwise, map the character
        map_s_to_t[char_s] = char_t
        map_t_to_s[char_t] = char_s

    return True

# Example test case
