def find_Extra(arr1, arr2, n):
    # Binary search to find the position of the first element in arr1 that is not equal to arr2
    left, right = 0, n - 1
    while left <= right:
        mid = (left + right) // 2
        if arr1[mid] != arr2[mid]:
            result = mid
            right = mid - 1
        else:
            left = mid + 1
    return result

