    # Traverse through remaining part and find the point where the condition fails.

    while i<n-1:
        if arr[i]>arr[i+1]:
            break
        i+=1

    # Now traverse from end of array till the point we found previously (inclusive).
    while i>=0:
        if arr[i]<arr[i-1]:
            break
        i-=1

    # If there's no point where condition fails then array can be sorted with first two elements.
    return True if i<0 else False

