import math

def lobb_num(n, m):
    if n < 2 or m < 1:
        return None  # Invalid input

    # Initialize variables
    total = 0
    exponent = 1

    # Calculate the Lobb number using the recursive formula
    while exponent <= m:
        if n % exponent == 0:
