def coin_change(coins, amount, min_coins=0):
    # Base case: if amount is 0, return the minimum number of coins used
    if amount == 0:
        return min_coins
    # If the list of coins is empty or amount is negative, return -1 (no solution)
    elif not coins or amount < 0:
        return -1
    else:
        # Recursive case: try each coin and move towards a solution
        for coin in coins:
            result = coin_change(coins, amount - coin, min_coins + 1)
            if result != -1:
                return result
    return -1

