def max_product(nums):
    # If there are less than two elements, return None as there's no way to have a product
    if len(nums) < 2:
        return None

    # Initialize variables for the largest and second-largest numbers
    max_num = float('-inf')
    sec_max_num = float('-inf')

    # Iterate through the list to find the largest and second-largest numbers
    for num in nums:
        if num > max_num:
            sec_max_num = max_num
            max_num = num
        elif num > sec_max_num and num != max_num:
            sec_max_num = num

    # Calculate the maximum product by multiplying the largest and second-largest numbers
    max_product = max_num * sec_max_num

    # Return the result
    return (max_num, sec_max_num, max_product)

