def rencontres_number(n, k):
    if n == 0 or k == 0: 
        return 1
    # Initialize a list to store results of subproblems
    dp = [0] * (n + 1)
    # The first row and column are all ones as there is only one way to select 0 items from any set
    for i in range(n+1): dp[i] = 1

    for i in range(2, n+1): 
        for j in range(1, min(i, k)+1): 
            dp[j] += dp[j-1]

    return dp[k]

