def dealnnoy_num(n, m):
    # Base cases for n and m
    if n == 0 or m == 0:
        return 0
    elif n == 1:
        return 1
    elif m == 1:
        return 1

    # Initialize the first two rows of the Delannoy triangle
    deln_noy_triangle = [[0]*(m+1) for _ in range(n+1)]
    deln_noy_triangle[0][0] = 1
    deln_noy_triangle[1][0], deln_noy_triangle[0][1] = 1, 1

    # Fill the triangle using the recurrence relation
    for i in range(2, n+1):
        for j in range(1, m+1):
            deln_noy_triangle[i][j] = deln_noy_triangle[i-1][j] + deln_noy_triangle[i-1][j-1]

    # Return the value at the nth row and mth column
    return deln_noy_triangle[n][m]

