    """
    Finds and returns the character that appears most frequently in the input string.

    :param s: The input string.
    :return: The character with the highest frequency.
    """
    # Use a dictionary to count occurrences of each character
    char_count = {}

    # Iterate through each character in the string
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the maximum occurrence
    max_freq = max(char_count.values())

    # Return the character that has the maximum occurrence
    for char, freq in char_count.items():
        if freq == max_freq:
            return char

