def char_frequency(text):
    freq_dict = {}
    for char in text:
        if char in freq_dict:
            freq_dict[char] += 1
        else:
            freq_dict[char] = 1
    return freq_dict

# Function to find the most common elements and their counts
def most_common_elem(text, n):
    # Count the frequency of each character in the text
    freq_dict = char_frequency(text)
    # Sort the characters by frequency in descending order
    sorted_chars = sorted(freq_dict.items(), key=lambda x: x[1], reverse=True)
    # Return the top 'n' most common elements and their counts
    return sorted_chars[:n]

# Test the function with the provided test case
assert most_common_elem('lkseropewdssafsdfafkpwe',3)==[('s', 4), ('e', 3), ('f', 3)]

