def max_similar_indices(list1, list2):
    # Use a set to store unique elements from both lists for efficient lookup
    elements = {x[0] for x in list1} | {x[1] for x in list2}

    # Create a dictionary to map each element to its indices in both lists
    index_map = {}
    for i, (a, b) in enumerate(list1 + list2):
        if a in elements:
            index_map[a] = i

    # Find the maximum index from the dictionary
    max_index = max(index_map.values(), default=0)

    # Filter the original lists to include only the tuples with the maximum index
    result = [(a, b) for a, b in list1 + list2 if index_map[a] == max_index]

    return result

