def subset(arr, n):
    # Initialize a counter for the number of subsets
    count = 0

    # Iterate through all possible subsets using nested loops
    for i in range(1 << n): 
        subset_set = set() 
        for j in range(n): 
            if (i & (1 << j)) > 0: 
                subset_set.add(arr[j])

        # Check if the current subset has distinct elements
        if len(subset_set) == n: 
            count += 1 

    return count

