def get_First_Set_Bit_Pos(n):
    if n <= 0:
        return 0  # No bits are set for non-positive integers

    pos = 0  # Initialize position to 0 (rightmost bit is at position 0)

    while n > 0:
        n >>= 1  # Right shift the number by one bit to check the next bit
        pos += 1  # Increment the position counter each time a bit is checked

        # Check if the least significant bit is set (bit is 1)
        if n & 1:
            break  # Break out of the loop when the most significant bit is encountered

    return pos

