    """
    Calculate the discriminant of a quadratic equation.

    Args:
        a (int): Coefficient of x^2.
        b (int): Coefficient of x.
        c (int): Constant term.

    Returns:
        tuple: A tuple containing two strings ("One solution" or "Two solutions") and the discriminant value.
    """
    # Calculate the discriminant
    d = b**2 - 4*a*c

    # Determine the nature of the roots based on the discriminant
    if d == 0:
        return ("One solution", d)
    elif d > 0:
        return ("Two solutions", d)
    else:
        return ("No real solutions", d)

