import cmath

def discriminant_value(a, b, c):
    # Calculate the discriminant of the quadratic equation ax^2 + bx + c = 0
    discriminant = b**2 - 4*a*c

    # Check if the discriminant is positive, negative, or zero and return the corresponding solution
    if discriminant > 0:
        x1 = (-b + cmath.sqrt(discriminant)) / (2*a)
        x2 = (-b - cmath.sqrt(discriminant)) / (2*a)
        return ("Two solutions", (x1, x2))
    elif discriminant == 0:
        x = -b / (2*a)
        return ("One solution", x)
    else:
        return ("No real solutions", None)

# Test the function with example test case
