def check(s):
    # define a string containing all vowels
    vowels = "AEIOUaeiou"

    # initialize a counter to 0
    count = 0

    # loop through each character in the input string
    for char in s:
        # if the character is a vowel, increment the counter
        if char in vowels:
            count += 1

    # if the counter is greater than or equal to 5, return 'accepted', otherwise 'rejected'
    if count >= 5:
        return 'accepted'
    else:
        return 'rejected'

