def floor_max(n, m, p):
    # Calculate the remainder of n divided by p
    rem = n % p

    # If the remainder is less than or equal to m, return the remainder
    if rem <= m:
        return rem

    # Otherwise, subtract m from rem and return it
    else:
        return rem - m

