def join_tuples(tuples_list):
    # Use a dictionary to store groups of similar initial elements
    grouped = {}
    for t in tuples_list:
        key = t[0]  # Use the first element as the key
        if key not in grouped:
            grouped[key] = [t]
        else:
            grouped[key].append(t)

    # Flatten the list of tuples into a single list of tuples
    result = [tuple(group) for group in grouped.values()]

    return result

# Example usage:
test_input = [(5, 6), (5, 7), (6, 8), (6, 10), (7, 13)]
expected_output = [(5, 6, 7), (6, 8, 10), (7, 13)]
assert join_tuples(test_input) == expected_output

